selected.compute:
options=read('/input/options')
existing=read('/output/selection')
if exists('/output/selection'):
    result=existing
else:
    result=[]
    for group in combinations(options,3):
        ids=[item['id'] for item in group]
        if valid(ids):
            result=ids
            break

selected.effects:
if not exists('/output/selection'):
    write('/output/selection',result)
    existing=result
else:
    existing=read('/output/selection')
if receipt('report')=='success':
    pass
elif receipt('report')=='unknown':
    status('report')
else:
    if status('report')=='not_sent':
        send('report','team',existing)
if exists('/tmp/cache'):
    delete('/tmp/cache')
